function renderCorrelationRules(){
  const body=document.querySelector('#table-correlation-rules tbody');if(!body)return;
  body.innerHTML=(correlationRules||[]).map((r,i)=>`<tr><td><strong>${esc(r.Name)}</strong><small>${esc(r.Description||'')}</small></td><td>${esc(r.WindowMinutes)} min<br><small>${esc(r.MinEvents)} events</small></td><td>${esc((r.RequiredTypes||[]).join(', ')||'Any 2 types')}</td><td>${esc((r.SequenceTypes||[]).join(' → ')||'Not ordered')}</td><td><span class="severity ${esc(r.Severity)}">${esc(r.Severity)}</span><br><small>+${esc(r.ScoreWeight)} score / +${esc(r.ConfidenceWeight)} confidence</small></td><td>${esc([...(r.MITRETactics||[]),...(r.MITRETechniques||[])].join(' · ')||'—')}</td><td>${r.Enabled?'Enabled':'Disabled'}${r.Builtin?' · built-in':''}</td><td>${r.Builtin?'Protected':`<button class="danger-btn cr-delete" data-index="${i}" data-requires-action="data_management">Delete</button>`}</td></tr>`).join('')||'<tr><td colspan="8">No correlation rules.</td></tr>';
}
function openCorrelationRule(){document.getElementById('correlation-rule-form').reset();document.getElementById('cr-window').value=60;document.getElementById('cr-min-events').value=2;document.getElementById('cr-score').value=20;document.getElementById('cr-confidence').value=15;document.getElementById('cr-enabled').checked=true;document.getElementById('correlation-rule-modal').hidden=false}
document.getElementById('correlation-rule-new').onclick=openCorrelationRule;
document.getElementById('correlation-rule-close').onclick=()=>document.getElementById('correlation-rule-modal').hidden=true;
document.getElementById('correlation-rule-form').onsubmit=async e=>{e.preventDefault();const body={Name:document.getElementById('cr-name').value.trim(),Description:document.getElementById('cr-description').value.trim(),Enabled:document.getElementById('cr-enabled').checked,WindowMinutes:Number(document.getElementById('cr-window').value),MinEvents:Number(document.getElementById('cr-min-events').value),RequiredTypes:splitCSV(document.getElementById('cr-required').value),SequenceTypes:splitCSV(document.getElementById('cr-sequence').value),Severity:document.getElementById('cr-severity').value,ScoreWeight:Number(document.getElementById('cr-score').value),ConfidenceWeight:Number(document.getElementById('cr-confidence').value),MITRETactics:splitCSV(document.getElementById('cr-tactics').value),MITRETechniques:splitCSV(document.getElementById('cr-techniques').value)};try{await api('/correlation-rules',{method:'POST',body:JSON.stringify(body)});document.getElementById('correlation-rule-modal').hidden=true;correlationRules=await api('/correlation-rules');renderCorrelationRules();await refreshAll()}catch(err){alert('Correlation rule save failed: '+err.message)}};
