document.querySelector('#table-analysis tbody').onclick=async e=>{const b=e.target.closest('.analysis-delete');if(!b)return;if(!confirm('Delete this analysis job and stored PCAP?'))return;try{await api('/analysis/jobs/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});refreshAll()}catch(err){alert(err.message)}};

function sensorSelection(){return [...document.querySelectorAll('.sensor-select:checked')].map(x=>x.dataset.id)}
function updateSensorBulk(){const ids=sensorSelection(),all=document.getElementById('sensors-all'),boxes=[...document.querySelectorAll('.sensor-select')];document.getElementById('sensors-start').hidden=!ids.length;document.getElementById('sensors-stop').hidden=!ids.length;document.getElementById('sensors-delete').hidden=!ids.length;document.getElementById('sensors-selection-count').textContent=ids.length?`${ids.length} selected`:'';if(all){all.checked=boxes.length>0&&ids.length===boxes.length;all.indeterminate=ids.length>0&&ids.length<boxes.length}}
function metric(obj,...path){let v=obj;for(const k of path){v=v?.[k]}return Number(v)||0}
function humanBytes(v){v=Number(v)||0;const u=['B','KB','MB','GB','TB'];let i=0;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v.toFixed(i?1:0)} ${u[i]}`}
function resizeCanvas(c,height=180){const dpr=Math.max(1,window.devicePixelRatio||1),w=Math.max(260,c.clientWidth||420);c.width=Math.round(w*dpr);c.height=Math.round(height*dpr);const x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);return{x,w,h:height}}
function counterRateSamples(samples,paths){return samples.map((sample,index)=>{const rates={};if(index===0){paths.forEach(p=>rates[p.name]=0);return {...sample,_counterRates:rates}}const previous=samples[index-1],elapsed=Math.max(.001,(new Date(sample.recorded_at)-new Date(previous.recorded_at))/60000);paths.forEach(p=>{const current=metric(sample,...p.path),before=metric(previous,...p.path),delta=current>=before?current-before:0;rates[p.name]=delta/elapsed});return {...sample,_counterRates:rates}})}
function counterDelta(samples,path){if(samples.length<2)return 0;let total=0;for(let i=1;i<samples.length;i++){const current=metric(samples[i],...path),previous=metric(samples[i-1],...path);if(current>=previous)total+=current-previous}return total}
function renderIntegrityQuality(samples){const target=document.getElementById('sensor-integrity-quality'),summary=document.getElementById('sensor-integrity-summary');if(!target||!summary)return;const gaps=counterDelta(samples,['metrics','tcp_reassembly','gap_recoveries']),overlaps=counterDelta(samples,['metrics','tcp_reassembly','overlap_conflicts']),packets=counterDelta(samples,['metrics','tcp_reassembly','tcp_packets_received']);const affected=gaps+overlaps,ratio=packets>0?affected/packets*100:null;let label='Unknown',kind='unknown',detail='Not enough TCP packet data in this range.';if(ratio!==null){if(ratio<.01){label='Excellent';kind='excellent'}else if(ratio<.1){label='Good';kind='good'}else if(ratio<1){label='Degraded';kind='degraded'}else{label='Poor';kind='poor'}detail=`${ratio.toFixed(ratio<.1?3:2)}% integrity events per observed TCP packet.`}target.className=`capture-quality capture-quality-${kind}`;target.textContent=label;summary.innerHTML=`<div><span>New gap recoveries</span><strong>${gaps.toLocaleString()}</strong><small>Missing sequence ranges recovered</small></div><div><span>New overlap conflicts</span><strong>${overlaps.toLocaleString()}</strong><small>Conflicting overlapping payloads</small></div><div><span>Capture quality</span><strong>${esc(label)}</strong><small>${esc(detail)}</small></div>`}
function drawMetricLine(id,samples,series){const c=document.getElementById(id);if(!c)return;const {x,w,h}=resizeCanvas(c,180);x.clearRect(0,0,w,h);const pad={l:45,r:14,t:12,b:25},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;const vals=samples.flatMap(s=>series.map(q=>q.value(s)));const max=Math.max(1,...vals);x.strokeStyle='#2a3648';x.lineWidth=1;x.beginPath();x.moveTo(pad.l,pad.t);x.lineTo(pad.l,pad.t+ph);x.lineTo(pad.l+pw,pad.t+ph);x.stroke();x.font='11px ui-monospace,monospace';x.fillStyle='#8393ab';x.textAlign='right';x.fillText(series[0].format?series[0].format(max):Math.round(max),pad.l-6,pad.t+5);x.fillText('0',pad.l-6,pad.t+ph);series.forEach((q,si)=>{x.strokeStyle=si?'#e8a33d':'#3fbfb0';x.lineWidth=2;x.beginPath();samples.forEach((s,i)=>{const px=pad.l+(samples.length<2?0:i/(samples.length-1))*pw,py=pad.t+ph-(q.value(s)/max)*ph;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()});if(samples.length){x.textAlign='left';x.fillText(new Date(samples[0].recorded_at).toLocaleTimeString(),pad.l,pad.t+ph+17);x.textAlign='right';x.fillText(new Date(samples.at(-1).recorded_at).toLocaleTimeString(),pad.l+pw,pad.t+ph+17)}}
let selectedMetricSensor='';async function openSensorMetrics(id){selectedMetricSensor=id;const s=sensors.find(x=>(x.id??x.ID)===id);document.getElementById('sensor-metrics-title').textContent=`Sensor metrics · ${s?.name||id}`;document.getElementById('sensor-metrics-subtitle').textContent=`${s?.hostname||'—'} · ${s?.capture_interface||'—'} · ${s?.capture_backend||'—'}`;document.getElementById('sensor-metrics-modal').hidden=false;await loadSensorMetricHistory()}
async function loadSensorMetricHistory(){if(!selectedMetricSensor)return;const range=document.getElementById('sensor-metrics-range').value;const rows=await api(`/sensors/${encodeURIComponent(selectedMetricSensor)}/metrics?range=${range}`);const last=rows.at(-1)||{},tcp=last.metrics?.tcp_reassembly||{},cap=last.metrics?.capture||{},sys=last.metrics?.system||{};document.getElementById('sensor-metrics-kpis').innerHTML=[['Health',last.health_state||'unknown'],['Packets/s',Math.round(metric(last,'metrics','capture','packets_per_second')).toLocaleString()],['Traffic/s',humanBytes(metric(last,'metrics','capture','bytes_per_second'))],['TCP reassembly',tcp.enabled?(tcp.running?'running':'stopped'):'disabled'],['TCP packets/s',Math.round(metric(last,'metrics','tcp_reassembly','tcp_packets_per_second')).toLocaleString()],['TCP share',`${metric(last,'metrics','tcp_reassembly','tcp_packet_percent').toFixed(1)}%`],['Active streams',metric(last,'metrics','tcp_reassembly','active_connections').toLocaleString()],['Streams opened',metric(last,'metrics','tcp_reassembly','connections_opened_total').toLocaleString()],['Streams closed',metric(last,'metrics','tcp_reassembly','connections_closed_total').toLocaleString()],['TCP segments',metric(last,'metrics','tcp_reassembly','segments_seen').toLocaleString()],['Stream chunks',metric(last,'metrics','tcp_reassembly','chunks_emitted').toLocaleString()],['Buffered',humanBytes(metric(last,'metrics','tcp_reassembly','buffered_bytes'))],['Gap recoveries',metric(last,'metrics','tcp_reassembly','gap_recoveries').toLocaleString()],['Overlap conflicts',metric(last,'metrics','tcp_reassembly','overlap_conflicts').toLocaleString()],['Sync failures',last.sync?.consecutive_failures||0]].map(([a,b])=>`<div class="kpi-card"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');drawMetricLine('sensor-chart-pps',rows,[{value:s=>metric(s,'metrics','capture','packets_per_second')}]);drawMetricLine('sensor-chart-bps',rows,[{value:s=>metric(s,'metrics','capture','bytes_per_second'),format:humanBytes}]);drawMetricLine('sensor-chart-streams',rows,[{value:s=>metric(s,'metrics','tcp_reassembly','active_connections')}]);drawMetricLine('sensor-chart-buffered',rows,[{value:s=>metric(s,'metrics','tcp_reassembly','buffered_bytes'),format:humanBytes}]);drawMetricLine('sensor-chart-memory',rows,[{value:s=>metric(s,'metrics','system','memory_alloc_bytes'),format:humanBytes}]);const integrityRows=counterRateSamples(rows,[{name:'gaps',path:['metrics','tcp_reassembly','gap_recoveries']},{name:'overlaps',path:['metrics','tcp_reassembly','overlap_conflicts']}]);drawMetricLine('sensor-chart-integrity',integrityRows,[{value:s=>s._counterRates?.gaps||0,format:v=>`${v.toFixed(v<10?1:0)}/min`},{value:s=>s._counterRates?.overlaps||0,format:v=>`${v.toFixed(v<10?1:0)}/min`}]);renderIntegrityQuality(rows);document.getElementById('sensor-metrics-details').innerHTML=objectRows({uptime_seconds:last.uptime_seconds,capture:last.capture,tcp_reassembly:tcp,versions:last.versions,sync:last.sync,health_reasons:last.health_reasons})}
async function loadHealthcheck(){try{healthcheckData=await api('/healthcheck');renderHealthcheck()}catch(e){console.error('healthcheck',e)}}
function renderHealthcheck(){const h=healthcheckData?.central||{},rows=healthcheckData?.sensors||[];document.getElementById('health-central-kpis').innerHTML=[['Healthy sensors',h.sensors_healthy||0],['Warning',h.sensors_warning||0],['Critical',h.sensors_critical||0],['Offline',h.sensors_offline||0],['Database',h.database_ok?'Healthy':'Unavailable'],['DB latency',`${Number(h.database_latency_ms||0).toFixed(1)} ms`],['Central memory',humanBytes(h.memory_alloc_bytes)],['Goroutines',h.goroutines||0]].map(([a,b])=>`<div class="kpi-card"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');document.getElementById('health-central-status').innerHTML=objectRows({recorded_at:time(h.recorded_at),uptime_seconds:h.uptime_seconds,memory_system:humanBytes(h.memory_sys_bytes),heap_objects:h.heap_objects,database_latency_ms:Number(h.database_latency_ms||0).toFixed(2)});document.getElementById('health-sensor-summary').innerHTML=['healthy','warning','critical','offline'].map(k=>`<div class="health-summary-item health-${k}"><span>${k}</span><strong>${rows.filter(x=>x.health_state===k).length}</strong></div>`).join('');document.querySelector('#table-health tbody').innerHTML=rows.map(x=>`<tr class="health-row" data-id="${esc(x.sensor_id)}"><td>${esc(x.sensor_id)}</td><td><span class="sensor-state sensor-state-${esc(x.health_state)}">${esc(x.health_state)}</span></td><td>${esc((x.health_reasons||[]).join('; ')||'No active operational issue')}</td><td>${time(x.recorded_at)}</td><td>${Math.round(metric(x,'metrics','capture','packets_per_second')).toLocaleString()}</td><td>${humanBytes(metric(x,'metrics','capture','bytes_per_second'))}/s</td><td>${metric(x,'metrics','capture','drop_rate_percent').toFixed(2)}%</td><td>${metric(x,'metrics','system','cpu_percent').toFixed(1)}%</td><td>${humanBytes(metric(x,'metrics','system','memory_alloc_bytes'))}</td><td>${metric(x,'metrics','pipeline','event_queue_depth')}</td><td>${metric(x,'metrics','tcp_reassembly','active_connections')}</td><td>${esc(x.versions?.threat_intel||'—')}</td><td>${esc(x.versions?.config||'—')}</td></tr>`).join('');const diag=healthcheckData?.diagnostics||{},target=document.getElementById('health-pipeline-diagnostics');if(target)target.innerHTML=rows.map(sensor=>`<section class="diagnostic-sensor"><h3>${esc(sensor.sensor_id)}</h3>${(diag[sensor.sensor_id]||[]).map(stage=>`<div class="diagnostic-stage diagnostic-${esc(stage.status)}"><span class="diagnostic-dot"></span><div><strong>${esc(stage.stage)}</strong><small>${esc(stage.detail||'')}</small></div><span class="diagnostic-value">${Number(stage.value||0).toLocaleString()} ${esc(stage.unit||'')}</span><span class="sensor-state sensor-state-${stage.status==='failed'?'critical':stage.status==='degraded'?'warning':'healthy'}">${esc(stage.status)}</span></div>`).join('')}</section>`).join('')||'<div class="empty-dashboard">No sensor diagnostics available</div>'}
function renderSensors(){sensors=Array.isArray(sensors)?sensors:[];populateRuleSensors();populateAnalysisSensors();renderSegmentationSensorList();populateITOTSensorList();const metricsBySensor=new Map((sensorMetrics||[]).map(x=>[x.sensor_id,x]));document.querySelector('#table-sensors tbody').innerHTML=sensors.map(s=>{const id=s.id??s.ID,status=String(s.status??s.Status??'unknown').toLowerCase(),m=metricsBySensor.get(id),hs=m?.health_state||status;return `<tr class="sensor-row" data-id="${esc(id)}"><td><input type="checkbox" class="sensor-select" data-id="${esc(id)}" aria-label="Select sensor ${esc(id)}"></td><td>${esc(id)}</td><td>${esc(s.name??s.Name)}</td><td>${esc(s.site_id??s.SiteID)}</td><td><span class="sensor-state sensor-state-${esc(hs)}">${esc(hs)}</span></td><td>${esc(s.hostname??s.Hostname)}</td><td>${esc(s.version??s.Version)}</td><td>${esc(s.go_version??s.GoVersion??'—')}</td><td>${esc(s.libpcap_version??s.LibpcapVersion??'—')}</td><td>${esc(s.gopacket_version??s.GopacketVersion??'—')}</td><td>${esc(s.capture_backend??s.CaptureBackend??'—')}</td><td>${esc(s.capture_interface??s.CaptureInterface??'—')}</td><td>${esc(s.capture_snaplen??s.CaptureSnaplen??'—')}</td><td>${(s.capture_promiscuous??s.CapturePromiscuous)?'yes':'no'}</td><td>${time(s.last_heartbeat_at??s.LastHeartbeatAt??s.last_seen??s.LastSeen)}</td><td>${time(s.last_data_received_at??s.LastDataReceivedAt)}</td><td><span class="sensor-state sensor-state-${esc(String(s.sync_status??s.SyncStatus??'unknown').toLowerCase())}">${esc(s.sync_status??s.SyncStatus??'unknown')}</span></td><td>${esc(s.pending_records??s.PendingRecords??0)}</td><td title="${esc(s.last_sync_error??s.LastSyncError??'')}">${esc((s.last_sync_error??s.LastSyncError??'—').slice(0,60))}</td></tr>`}).join('');updateSensorBulk()}
async function sensorAction(action){const ids=sensorSelection();if(!ids.length)return;const verb=action==='stop'?'stop capture on':'start capture on';if(!confirm(`${verb} ${ids.length} selected sensor(s)?`))return;const start=document.getElementById('sensors-start'),stop=document.getElementById('sensors-stop');start.disabled=stop.disabled=true;try{await api('/sensors/actions',{method:'POST',body:JSON.stringify({action,sensor_ids:ids})});document.getElementById('sensors-selection-count').textContent=`${action} queued for ${ids.length} sensor(s)`;setTimeout(refreshAll,1200)}catch(err){alert(`Sensor ${action} failed: ${err.message}`)}finally{start.disabled=stop.disabled=false}}
async function deleteSensors(){
  const ids=sensorSelection();if(!ids.length)return;
  const confirmation=prompt(`This deletes ${ids.length} sensor(s) and ALL their history (topology, alerts, analysis jobs) permanently. A sensor that's still running will automatically re-enroll. Its local SQLite state is not deleted by this action, so locally persisted assets/alerts can be uploaded again unless the sensor is reset separately. Type DELETE to continue.`);
  if(confirmation!=='DELETE')return;
  const btn=document.getElementById('sensors-delete');btn.disabled=true;
  try{
    await Promise.all(ids.map(id=>api(`/sensors/${encodeURIComponent(id)}`,{method:'DELETE'})));
    document.getElementById('sensors-selection-count').textContent=`Deleted ${ids.length} sensor(s)`;
    refreshAll();
  }catch(err){alert(`Sensor delete failed: ${err.message}`)}
  finally{btn.disabled=false}
}
document.querySelector('#table-sensors tbody').addEventListener('change',e=>{if(e.target.matches('.sensor-select'))updateSensorBulk()});document.getElementById('sensors-all').addEventListener('change',e=>{document.querySelectorAll('.sensor-select').forEach(x=>x.checked=e.target.checked);updateSensorBulk()});document.getElementById('sensors-start').onclick=()=>sensorAction('start');document.getElementById('sensors-stop').onclick=()=>sensorAction('stop');document.getElementById('sensors-delete').onclick=()=>deleteSensors();

function openDashboardTab(tab){
  if(!canView(tab))return;
  const button=document.querySelector(`.tab[data-tab="${tab}"]`);
  if(button)button.click();
}
function dashboardStatus(sensor){
  const status=String(sensor.status??sensor.Status??'offline').toLowerCase();
  if(status==='running'||status==='online'||status==='active')return 'running';
  if(status==='stopped'||status==='paused'||status==='disabled')return 'stopped';
  return 'offline';
}
function dashboardBars(target,items,total,severity=false){
  const el=document.getElementById(target);if(!el)return;
  if(!items.length||!total){el.innerHTML='<div class="empty-dashboard">No data available</div>';return}
  el.innerHTML=items.map(([name,count])=>`<div class="bar-row" ${severity?`data-severity="${esc(String(name).toLowerCase())}"`:''}><span class="bar-label" title="${esc(name)}">${esc(name)}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max(2,Math.round(count/total*100))}%"></span></span><span class="bar-value">${count}</span></div>`).join('');
}
function renderDashboard(){
  const sensorCounts={running:0,stopped:0,offline:0};
  (sensors||[]).forEach(s=>sensorCounts[dashboardStatus(s)]++);
  const openAlerts=(alerts||[]).filter(a=>String(a.Status??a.status??'new').toLowerCase()==='new');
  const activeRules=(rules||[]).filter(r=>Boolean(r.Enabled??r.enabled));
  const unconfirmedAssets=(assets||[]).filter(a=>(a.Confirmed??a.confirmed)===false).length;
  const pendingJobs=(analysisJobs||[]).filter(j=>['queued','pending','running','processing'].includes(String(j.status??j.Status??'').toLowerCase()));
  document.getElementById('dashboard-sensors-running').textContent=sensorCounts.running;
  document.getElementById('dashboard-sensors-stopped').textContent=sensorCounts.stopped;
  document.getElementById('dashboard-sensors-offline').textContent=sensorCounts.offline;
  const authoritativeOpen=Number.isFinite(Number(alertStats?.open))?Number(alertStats.open):openAlerts.length;document.getElementById('dashboard-alerts-open').textContent=authoritativeOpen;
  document.getElementById('dashboard-assets').textContent=(assets||[]).length;
  document.getElementById('dashboard-assets-detail').textContent=`${unconfirmedAssets} unconfirmed`;
  document.getElementById('dashboard-rules').textContent=`${activeRules.length} / ${(rules||[]).length}`;
  document.getElementById('dashboard-tags').textContent=(tags||[]).length;
  document.getElementById('dashboard-analysis').textContent=pendingJobs.length;
  document.getElementById('dashboard-analysis-detail').textContent=pendingJobs.length?`${pendingJobs.filter(j=>String(j.status).toLowerCase()==='running').length} running · ${pendingJobs.length} pending`:'No pending jobs';
  document.getElementById('dashboard-unconfirmed-assets').textContent=unconfirmedAssets;
  const tiHits=openAlerts.filter(a=>['malicious_ip','malicious_domain'].includes(String(a.Type))).length;
  const c2lm=openAlerts.filter(a=>['c2_correlated','beacon','lateral_movement'].includes(String(a.Type))).length;
  const otAnomaly=openAlerts.filter(a=>['ot_value_anomaly','unexpected_write'].includes(String(a.Type))).length;
  const smbRiskCount=(smbObservations||[]).filter(smbRisk).length;
  document.getElementById('dashboard-ti').textContent=tiHits;
  document.getElementById('dashboard-c2lm').textContent=c2lm;
  document.getElementById('dashboard-ot-anomaly').textContent=otAnomaly;
  document.getElementById('dashboard-smb').textContent=smbRiskCount;
  document.getElementById('dashboard-refresh').textContent=new Date().toLocaleTimeString();
  const totalPPS=(sensorMetrics||[]).reduce((n,x)=>n+metric(x,'metrics','capture','packets_per_second'),0),totalStreams=(sensorMetrics||[]).reduce((n,x)=>n+metric(x,'metrics','tcp_reassembly','active_connections'),0);
  // Count each affected sensor only once. Metrics carry warning/critical health,
  // while the sensor registry is the reliable source for sensors that are
  // offline or stopped and therefore may not have a fresh metrics row.
  const operationalWarningSensors=new Set();
  (sensorMetrics||[]).forEach(x=>{if(['warning','critical','offline'].includes(String(x.health_state??x.HealthState??'').toLowerCase()))operationalWarningSensors.add(String(x.sensor_id??x.SensorID??x.id??x.ID??''))});
  (sensors||[]).forEach(x=>{const state=dashboardStatus(x);if(state==='offline'||state==='stopped')operationalWarningSensors.add(String(x.id??x.ID??x.sensor_id??x.SensorID??x.name??x.Name??''))});
  operationalWarningSensors.delete('');
  const healthWarnings=operationalWarningSensors.size;
  document.getElementById('dashboard-pps').textContent=Math.round(totalPPS).toLocaleString();document.getElementById('dashboard-streams').textContent=Math.round(totalStreams).toLocaleString();document.getElementById('dashboard-health-warnings').textContent=healthWarnings;
  const udp=udpTelemetry?.totals||{},udpRTT=Number(udp.udp_average_rtt||0),topUDP=String(udpTelemetry?.top_protocol||'');
  document.getElementById('dashboard-udp-active').textContent=Number(udp.udp_conversations_active||0).toLocaleString();
  document.getElementById('dashboard-udp-rtt').textContent=udpRTT?`${udpRTT.toFixed(2)} ms`:'—';
  document.getElementById('dashboard-udp-timeouts').textContent=Number(udp.udp_request_timeouts_total||0).toLocaleString();
  document.getElementById('dashboard-udp-protocol').textContent=topUDP?topUDP.toUpperCase():'—';
  const udpPackets=Number(udp.udp_packets_total||0),udpRateNow=Date.now();let udpPPS=0;
  if(udpPacketRateState&&udpPackets>=udpPacketRateState.packets)udpPPS=(udpPackets-udpPacketRateState.packets)/Math.max(1,(udpRateNow-udpPacketRateState.at)/1000);
  udpPacketRateState={packets:udpPackets,at:udpRateNow};
  const udpPacketEl=document.getElementById('dashboard-udp-packets');udpPacketEl.textContent=Math.round(udpPPS).toLocaleString();udpPacketEl.previousElementSibling.textContent='UDP packets/s';udpPacketEl.nextElementSibling.textContent='Since previous refresh';
  const profiled=(assets||[]).filter(a=>a.LastProfiledAt||a.ReconHostname||a.ReconVendor||a.ReconOS).length, unknownIdentity=(assets||[]).filter(a=>!(a.Hostname||a.ReconHostname)||!(a.Vendor||a.ReconVendor)||!a.ReconOS).length, reconActive=(reconnaissanceJobs||[]).filter(j=>['queued','running'].includes(j.status)).length;
  const dp=document.getElementById('dashboard-profiled');if(dp)dp.textContent=profiled;const du=document.getElementById('dashboard-unknown-identity');if(du)du.textContent=unknownIdentity;const dj=document.getElementById('dashboard-recon-jobs');if(dj)dj.textContent=reconActive;

  const staleAssets=(assets||[]).filter(a=>a.IdentityActive===false).length;
  const completeAssets=(assets||[]).filter(a=>(a.Hostname||a.ReconHostname)&&(a.Vendor||a.ReconVendor)&&a.ReconOS).length;
  const coverage=(assets||[]).length?Math.round(completeAssets/(assets||[]).length*100):0;
  const exposure=(vulnerabilities||[]).reduce((n,v)=>n+Number(v.StatusCounts?.confirmed||0)+Number(v.StatusCounts?.accepted_risk||0),0);
  const criticalCount=Number.isFinite(Number(alertStats?.open_critical))?Number(alertStats.open_critical):openAlerts.filter(a=>String(a.Severity??a.severity).toLowerCase()==='critical').length;
  const attention=criticalCount+sensorCounts.offline+exposure;
  document.getElementById('dashboard-attention').textContent=attention.toLocaleString();
  document.getElementById('dashboard-coverage').textContent=coverage+'%';
  document.getElementById('dashboard-stale-assets').textContent=staleAssets.toLocaleString();
  document.getElementById('dashboard-exposure').textContent=exposure.toLocaleString();
  const priorities=[];
  openAlerts.filter(a=>String(a.Severity??a.severity).toLowerCase()==='critical').slice(0,4).forEach(a=>priorities.push({kind:'Critical alert',message:a.Message??a.message??a.Type??'Critical detection',meta:`${a.SensorID??a.sensor_id??'—'} · ${time(a.LastSeen??a.last_seen)}`,tab:'alerts',level:'critical'}));
  (sensors||[]).filter(s=>dashboardStatus(s)==='offline').slice(0,3).forEach(s=>priorities.push({kind:'Sensor offline',message:s.name??s.Name??s.id??s.ID??'Sensor',meta:'Heartbeat unavailable',tab:'sensors',level:'critical'}));
  if(exposure)priorities.push({kind:'Vulnerability exposure',message:`${exposure} confirmed or accepted finding(s)`,meta:'Review remediation decisions',tab:'vulnerabilities',level:'high'});
  if(staleAssets)priorities.push({kind:'Inventory hygiene',message:`${staleAssets} stale asset(s)`,meta:'Validate or retire old identities',tab:'assets',level:'medium'});
  const priorityEl=document.getElementById('dashboard-priority');
  priorityEl.innerHTML=priorities.length?priorities.slice(0,7).map(x=>`<button class="priority-item priority-${esc(x.level)}" data-dashboard-tab="${esc(x.tab)}"><span class="priority-icon"></span><span><strong>${esc(x.kind)}</strong><b>${esc(x.message)}</b><small>${esc(x.meta)}</small></span><i>›</i></button>`).join(''):'<div class="empty-dashboard priority-clear"><strong>No immediate actions</strong><span>Current telemetry has no critical operational or security issue.</span></div>';
  const riskyIPs=new Set();openAlerts.forEach(a=>{const raw=JSON.stringify(a);(assets||[]).forEach(x=>{if(x.IP&&raw.includes(x.IP))riskyIPs.add(x.SensorID+'::'+x.IP)})});
  const riskBuckets=[['High',riskyIPs.size],['Needs profiling',unknownIdentity],['Stale',staleAssets],['Healthy',Math.max(0,(assets||[]).length-new Set([...riskyIPs]).size-unknownIdentity-staleAssets)]];
  const riskTotal=Math.max(1,riskBuckets.reduce((n,x)=>n+x[1],0));
  const riskEl=document.getElementById('dashboard-asset-risk');riskEl.innerHTML=`<div class="risk-donut" style="--risk-high:${Math.round(riskBuckets[0][1]/riskTotal*100)};--risk-profile:${Math.round(riskBuckets[1][1]/riskTotal*100)};--risk-stale:${Math.round(riskBuckets[2][1]/riskTotal*100)}"><div><strong>${(assets||[]).length}</strong><span>assets</span></div></div><div class="risk-legend">${riskBuckets.map(([name,count],i)=>`<button data-dashboard-tab="assets"><i class="risk-dot risk-dot-${i}"></i><span>${esc(name)}</span><strong>${count}</strong></button>`).join('')}</div>`;

  const severityOrder=['critical','high','medium','low','info'];
  const hasAuthoritativeSeverity=severityOrder.every(x=>Number.isFinite(Number(alertStats?.['open_'+x])));
  const severityCounts=new Map(severityOrder.map(x=>[x,hasAuthoritativeSeverity?Number(alertStats['open_'+x]):0]));
  if(!hasAuthoritativeSeverity)openAlerts.forEach(a=>{const key=String(a.Severity??a.severity??'info').toLowerCase();severityCounts.set(key,(severityCounts.get(key)||0)+1)});
  const severityItems=severityOrder.map(x=>[x[0].toUpperCase()+x.slice(1),severityCounts.get(x)||0]).filter(([,n])=>n>0);
  const severityMax=severityItems.reduce((m,[,n])=>Math.max(m,n),0);
  dashboardBars('dashboard-severity',severityItems,severityMax,true);

  const protocolCounts=new Map();
  (assets||[]).forEach(a=>(a.Protocols??a.protocols??[]).forEach(proto=>{const key=String(proto||'Unknown');protocolCounts.set(key,(protocolCounts.get(key)||0)+1)}));
  if(!protocolCounts.size)(tags||[]).forEach(t=>{const key=String(t.Protocol??t.protocol??'Unknown');protocolCounts.set(key,(protocolCounts.get(key)||0)+1)});
  const protocols=[...protocolCounts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,7);
  dashboardBars('dashboard-protocols',protocols,protocols.reduce((n,x)=>n+x[1],0));

  const recent=[...openAlerts].sort((a,b)=>new Date(b.LastSeen??b.last_seen??0)-new Date(a.LastSeen??a.last_seen??0)).slice(0,7);
  const recentEl=document.getElementById('dashboard-recent');
  recentEl.innerHTML=recent.length?recent.map(a=>`<div class="activity-item"><span class="activity-time">${time(a.LastSeen??a.last_seen)}</span><span class="activity-sensor">${esc(a.SensorID??a.sensor_id??'—')}</span><span class="activity-message"><span class="severity ${esc(String(a.Severity??a.severity??'info').toLowerCase())}">${esc(a.Severity??a.severity??'info')}</span>${esc(a.Message??a.message??a.Type??a.type??'Alert')}</span></div>`).join(''):'<div class="empty-dashboard">No open security alerts</div>';

  const learning=(baselines||[]).filter(b=>String(b.mode??b.Mode??'').toLowerCase()==='learning');
  document.getElementById('dashboard-baseline').textContent=learning.length?`Learning on ${learning.length} sensor(s)`:(baselines||[]).length?'Monitoring':'No data';
  const latest=[...(backups||[])].sort((a,b)=>new Date(b.created_at??b.CreatedAt??0)-new Date(a.created_at??a.CreatedAt??0))[0];
  document.getElementById('dashboard-backup').textContent=latest?time(latest.created_at??latest.CreatedAt):'Never';

  const criticalOpen=severityCounts.get('critical')||0;
  const health=document.getElementById('dashboard-health'),title=document.getElementById('dashboard-health-title'),detail=document.getElementById('dashboard-health-detail');
  health.className='health-banner '+(sensorCounts.offline||criticalOpen?'health-critical':sensorCounts.stopped||openAlerts.length?'health-warning':'health-healthy');
  if(sensorCounts.offline||criticalOpen){title.textContent='Critical';detail.textContent=[sensorCounts.offline?`${sensorCounts.offline} sensor(s) offline`:'',criticalOpen?`${criticalOpen} critical alert(s)`:'' ].filter(Boolean).join(' · ')}
  else if(sensorCounts.stopped||authoritativeOpen){title.textContent='Warning';detail.textContent=[sensorCounts.stopped?`${sensorCounts.stopped} sensor(s) stopped`:'',authoritativeOpen?`${authoritativeOpen} open alert(s)`:'' ].filter(Boolean).join(' · ')}
  else{title.textContent='Healthy';detail.textContent='Sensors running and no open alerts'}
  drawDailyBarChart('dashboard-alerts-trend',trends.AlertsByDay,30);
  drawDailyBarChart('dashboard-assets-trend',trends.NewAssetsByDay,30);
}
document.getElementById('view-dashboard').addEventListener('click',e=>{const target=e.target.closest('[data-dashboard-tab]');if(target)openDashboardTab(target.dataset.dashboardTab)});

function renderBaseline(){const learning=baselines.filter(b=>b.mode==='learning'),d=document.getElementById('baseline-dot'),t=document.getElementById('baseline-text');if(learning.length){d.className='dot learning';const ends=learning.map(x=>new Date(x.learning_ends_at)).filter(x=>!isNaN(x)).sort((a,b)=>a-b)[0];t.textContent=`Learning ${learning.length}/${baselines.length}${ends?' · until '+ends.toLocaleTimeString():''} · alerts suppressed`}else{d.className='dot monitoring';t.textContent=baselines.length?'Monitoring':'No baseline data'}}
function renderSettings(){
  const extra=document.getElementById('settings-runtime-config');if(!extra)return;const groups=settings.RuntimeConfig||{};extra.innerHTML=Object.entries(groups).map(([group,values])=>`<section class="settings-config-group"><h3>${esc(group)}</h3><dl class="status-list">${Object.entries(values||{}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd class="wrap-anywhere">${esc(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join('')}</dl></section>`).join('');loadPermissionAudit()
}



async function loadPermissionAudit(){
  const panel=document.getElementById('permission-audit-panel');if(!panel||!can('users_roles_manage'))return;
  panel.hidden=false;
  try{const data=await api('/security/permission-audit'),rows=data.endpoints||[],summary=data.summary||{};document.querySelector('#table-permission-audit tbody').innerHTML=rows.map(x=>`<tr><td><strong>${esc(x.method)}</strong></td><td><code>${esc(x.path)}</code></td><td><span class="permission-control">${esc(x.kind)}:${esc(x.permission)}</span></td><td class="${x.audited?'permission-audit-ok':'permission-audit-warn'}">${x.audited?'mutations logged':'read/export'}</td></tr>`).join('');const badge=document.getElementById('permission-audit-summary');badge.textContent=`${summary.server_side_protected||0}/${summary.sensitive_endpoints||0} protected`;badge.className='status-pill '+((summary.unprotected||0)?'degraded':'healthy')}catch(err){panel.hidden=true}
}
async function downloadDiagnostics(){
  const button=document.getElementById('download-diagnostics');button.disabled=true;
  try{const r=await fetch('/v1/data/diagnostics',{credentials:'include'});if(!r.ok)throw new Error(await r.text());const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;const cd=r.headers.get('Content-Disposition')||'';a.download=(cd.match(/filename="?([^";]+)"?/)||[])[1]||'otlens-diagnostics.zip';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}catch(err){alert('Diagnostics export failed: '+err.message)}finally{button.disabled=false}
}
